const TRQ = TEAM_ROCKET_QUESTS as Record<string, Record<string, unknown>>;
Object.keys(TRQ).forEach((questId) => {
    const quest = TRQ[questId];
    if (!quest) return;
    const rewards = quest.rewards as { tokens?: number };
    if (!rewards || typeof rewards.tokens !== 'number') return;
    const originalTokens = Math.max(0, rewards.tokens);
    rewards.tokens = originalTokens > 0 ? Math.max(1, Math.floor(originalTokens / 2)) : 0;
});

