(function applyBalanceTowerShopCosts() {
    const tm = BALANCE && BALANCE.SHOP_COSTS && BALANCE.SHOP_COSTS.TOWER_MARKS;
    if (!tm || typeof TOWER_SHOP_ITEMS === 'undefined') return;
    const towerItems = TOWER_SHOP_ITEMS as Record<string, unknown>;
    const tmRates = tm as unknown as Record<string, unknown>;
    Object.keys(tmRates).forEach((k) => {
        const entry = towerItems[k] as Record<string, unknown> | undefined;
        const rate = tmRates[k];
        if (!entry || rate == null) return;
        if (typeof rate === 'object' && !Array.isArray(rate)) {
            const scaled = rate as { base?: number; multiplier?: number };
            if (scaled.base != null) entry.cost = scaled.base;
            if (scaled.multiplier != null) entry.costMultiplier = scaled.multiplier;
        } else {
            entry.cost = rate;
        }
    });
})();

