/** Production tiers ordered by berries/hour (fastest → slowest) → Tier I…IX. */
export const BERRY_PRODUCTION_TIER_ORDER: readonly BerryProductionTier[] = Object.freeze([
    'status',
    'hp',
    'pp',
    'confusion',
    'capture',
    'ev',
    'typeResist',
    'poffin',
    'special',
]);

const TIER_ROMAN: readonly string[] = ['I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII', 'IX'];

/** Player-facing production tier label (e.g. "Tier I"). Internal keys unchanged. */
export function getBerryProductionTierLabel(tier: BerryProductionTier): string {
    const index = BERRY_PRODUCTION_TIER_ORDER.indexOf(tier);
    const roman = (index >= 0 ? TIER_ROMAN[index] : undefined) ?? 'I';
    return `Tier ${roman}`;
}

function buildBerryItems(): Record<string, BerryItemDef> {
    const out: Record<string, BerryItemDef> = {};
    for (const key of BERRY_DEX_KEYS) {
        const meta = BERRY_META[key];
        out[key] = {
            name: meta.name,
            description: `Berry grown on the Miltank farm tree. Tier: ${getBerryProductionTierLabel(meta.tier)}.`,
            icon: '🫐',
            img: BERRY_SPRITE(meta.slug),
            rarity: TIER_RARITY[meta.tier],
            type: 'berry',
            berryTier: meta.tier,
            noRandomDrop: true,
        };
    }
    return out;
}

export const BERRIES: Record<string, BerryItemDef> = buildBerryItems();

