const RECIPE_BY_BERRY = new Map(BERRY_TREE_RECIPES.map((r) => [r.berryKey, r]));

export function getBerryTreeRecipe(berryKey: string): BerryTreeRecipeDef | null {
    return RECIPE_BY_BERRY.get(berryKey) ?? null;
}

export function getBerryProductionTier(berryKey: string): BerryProductionTier {
    const meta = BERRY_META[berryKey as BerryDexKey];
    return meta?.tier ?? 'status';
}

/** Sort comparator: production tier I→IX, then berryKey. */
export function compareBerryKeysByProductionTier(a: string, b: string): number {
    const tierA = BERRY_PRODUCTION_TIER_ORDER.indexOf(getBerryProductionTier(a));
    const tierB = BERRY_PRODUCTION_TIER_ORDER.indexOf(getBerryProductionTier(b));
    if (tierA !== tierB) return tierA - tierB;
    return a.localeCompare(b);
}

export function getBerryBerriesPerHour(berryKey: string): number {
    const tier = getBerryProductionTier(berryKey);
    return BERRY_TREE.tierRates[tier].berriesPerHour
        * BERRY_TREE.productionTestMult
        * BERRY_TREE.berryProductionSpeedMult;
}

/** Player-facing rate (no productionTestMult). */
export function getBerryDisplayBerriesPerHour(berryKey: string, productionMult = 1): number {
    const tier = getBerryProductionTier(berryKey);
    const mult = Math.max(1, Number(productionMult) || 1);
    return BERRY_TREE.tierRates[tier].berriesPerHour
        * BERRY_TREE.berryProductionSpeedMult
        * mult;
}

export function getBerryRecipeSlotCount(berryKey: string): number {
    return getBerryTreeRecipe(berryKey)?.ingredients.length ?? 0;
}

/** Items allowed in the discovery combiner (excludes CT, held items, key items, berries, mulches). */
export function isBerryCombineEligibleItemKey(itemKey: string): boolean {
    if (!itemKey || itemKey.startsWith('ct_')) return false;
    if (itemKey.endsWith('_berry')) return false;
    if (itemKey in BERRY_MULCHES) return false;
    if (itemKey.startsWith('hatch_capsule') || itemKey === 'instant_hatch_capsule') return false;
    if (itemKey === MIAOUSS_STATUETTE_ITEM_KEY) return false;
    if (itemKey in HELD_ITEMS) return false;
    if (KEY_ITEMS[itemKey]?.type === 'key_item') return false;
    return true;
}
