(function applyBalanceTokenShopCosts() {
    const sc = BALANCE && BALANCE.SHOP_COSTS;
    if (!sc || typeof SHOP_ITEMS === 'undefined') return;
    function mergeCosts(map: Record<string, unknown>) {
        if (!map) return;
        const shop = SHOP_ITEMS as Record<string, unknown>;
        Object.keys(map).forEach((k) => {
            if (shop[k]) (shop[k] as Record<string, unknown>).cost = map[k];
        });
    }
    mergeCosts(sc.TOKEN);
    mergeCosts(sc.TOKEN_CT);
})();

